content.arguments:
{"description": "下载候选头像图片", "command": "$dir="C:\Users\九幽\.dsh-qq\avatar"; New-Item -ItemType Directory -Force -Path $dir | Out-Null
$targets = @(
 @{n='u1'; url='https://unsplash.com/photos/blurred-city-lights-through-window-DVz53TEIaWg'},
 @{n='u2'; url='https://unsplash.com/photos/woman-looking-through-window-with-reflection-d_Zq9XwB2P8'}
)
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
foreach($t in $targets){
  try{
    $r = Invoke-WebRequest -Uri $t.url -UseBasicParsing -TimeoutSec 30 -Headers @{'User-Agent'='Mozilla/5.0'}
    $m = [regex]::Matches($r.Content,'https://images\.unsplash\.com/photo-[A-Za-z0-9\-_]+')
    if($m.Count -gt 0){
      $img = $m[0].Value + '?w=800&q=80&fit=crop'
      $out = Join-Path $dir ($t.n + '.jpg')
      Invoke-WebRequest -Uri $img -OutFile $out -UseBasicParsing -TimeoutSec 60
      "$($t.n) OK -> $out ($((Get-Item $out).Length) bytes) $img"
    } else { "$($t.n) 没找到图 URL" }
  } catch { "$($t.n) 失败: $($_.Exception.Message)" }
}"}

