content.arguments:
{"file_path": "C:/Users/九幽/.dsh-qq/restart-qqbot.ps1", "content": "# 重启 qqbot 宿主（让 onebot 插件白名单补丁生效）
# 由林晚在 2026-10-26 生成，日志在 .dsh-qq\restart-log.txt
$ErrorActionPreference = 'Continue'
$log = 'C:\Users\九幽\.dsh-qq\restart-log.txt'
function W($m) { "$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') $m" | Out-File -FilePath $log -Append -Encoding utf8 }

$exe = 'E:\dsh\DeepSeek Harness.exe'
$cli = 'E:\dsh\resources\app.asar\dsh\node_modules\@deepseek-ai\dsh-desktop-host\lib\cli.js'
$oldPid = 35700

Start-Sleep -Seconds 20
W "开始重启，准备结束 PID $oldPid"
try {
    Stop-Process -Id $oldPid -Force -ErrorAction Stop
    W "已结束 $oldPid"
} catch {
    W "结束失败: $($_.Exception.Message)"
}
Start-Sleep -Seconds 5
try {
    Start-Process -FilePath $exe -ArgumentList "`"$cli`" --profile qqbot --host 127.0.0.1 --port 8790 --no-open"
    W "已拉起新进程"
} catch {
    W "拉起失败: $($_.Exception.Message)"
}

$ok = $false
for ($i = 0; $i -lt 40; $i++) {
    Start-Sleep -Seconds 2
    $l = Get-NetTCPConnection -State Listen -LocalPort 8790 -ErrorAction SilentlyContinue
    if ($l) { $ok = $true; W "8790 已监听（第 $($i*2) 秒），PID=$($l.OwningProcess -join ',')"; break }
}
if (-not $ok) { W "警告：60 秒内 8790 未监听，可能需要手动启动" }
W "重启流程结束"
"}

