content.arguments:
{"content": "# Delayed qqbot restart, launched by Task Scheduler (detached from the DSH process tree).
# ASCII-only content AND ASCII-only path on purpose: PowerShell 5.1 under Task Scheduler
# decodes script files and paths with the ANSI code page, so non-ASCII breaks it.
$base = Join-Path $env:USERPROFILE '.dsh-qq'
$log  = Join-Path $base 'restart-log.txt'
function W($m) { "$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') $m" | Out-File -FilePath $log -Append -Encoding utf8 }
W "wrapper started (pid $PID)"
W "USERPROFILE=$env:USERPROFILE"
Start-Sleep -Seconds 15
W "calling Restart-QqBot.ps1"
$restart = Join-Path $env:USERPROFILE 'xqztest\dsh-qq-bot\scripts\Restart-QqBot.ps1'
W "restart script exists: $(Test-Path $restart)"
try {
    & $restart -DshQqHome $base *>&1 | Out-File -FilePath $log -Append -Encoding utf8
    W "restart script returned"
} catch {
    W "restart failed: $($_.Exception.Message)"
}
for ($i = 0; $i -lt 20; $i++) {
    Start-Sleep -Seconds 2
    $listen = Get-NetTCPConnection -State Listen -LocalPort 8790 -ErrorAction SilentlyContinue
    if ($listen) { W "port 8790 listening PID=$($listen.OwningProcess -join ',')"; break }
}
W "wrapper done"
", "file_path": "C:/ProgramData/dsh-qq/restart-wrapper.ps1"}

