content.arguments:
{"description": "查询 DeepSeek API 余额", "command": "$f="$env:USERPROFILE\.dsh\.credentials.yaml"
$raw=Get-Content $f -Raw -Encoding utf8
$m=[regex]::Match($raw,'DEEPSEEK_API_KEY\s*:\s*(\S+)')
if(-not $m.Success){ '没找到 DEEPSEEK_API_KEY'; exit }
$key=$m.Groups[1].Value.Trim('"',"'")
if($key.StartsWith('ref:') -or $key.Length -lt 10){ "键不是明文（$($key.Substring(0,[Math]::Min(20,$key.Length)))…），需要别的方式" ; }
[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12
try{
  $r=Invoke-RestMethod -Uri 'https://api.deepseek.com/user/balance' -Headers @{Authorization="Bearer $key";Accept='application/json'} -TimeoutSec 30
  $r | ConvertTo-Json -Depth 6
}catch{ "请求失败: $($_.Exception.Message)" }"}

