content.arguments:
{"description": "统计记忆与会话的当前规模", "command": "$h="$env:USERPROFILE\.dsh-qq"
"记忆仓库:"
if(Test-Path "$h\memory-repo"){ Get-ChildItem "$h\memory-repo" -Recurse -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum | ForEach-Object { "  文件数=$($_.Count) 合计=$([math]::Round($_.Sum/1KB,1)) KB" } }
Get-ChildItem "$h\memory-repo" -Directory -ErrorAction SilentlyContinue | Select-Object Name
"short/:"
Get-ChildItem "$h\memory-repo\short" -File -ErrorAction SilentlyContinue | ForEach-Object { "  $($_.Name) $([math]::Round($_.Length/1KB,1))KB" }
"long/:"
Get-ChildItem "$h\memory-repo\long" -File -ErrorAction SilentlyContinue | ForEach-Object { "  $($_.Name) $([math]::Round($_.Length/1KB,1))KB" }
"会话归档:"
Get-ChildItem "$h\sessions" -Recurse -File -Filter *.jsonl -ErrorAction SilentlyContinue | Measure-Object Length -Sum | ForEach-Object { "  $($_.Count) 个文件, $([math]::Round($_.Sum/1MB,2)) MB" }
"GitHub 同步:"
$s="$h\memory-sync-status.json"; if(Test-Path $s){ $j=Get-Content $s -Raw -Encoding utf8 | ConvertFrom-Json; "  最近拉取=$($j.lastPull) 推送=$($j.lastLongPush) 错误=$($j.lastError) 仓库大小=$([math]::Round($j.repoSizeBytes/1KB,1))KB" }"}

