content.arguments:
{"command": "schtasks.exe /run /tn "FreeLLMAPIOnce" 2>&1 | Out-String
Start-Sleep -Seconds 9
Get-NetTCPConnection -State Listen -LocalPort 3010 -ErrorAction SilentlyContinue | Select-Object LocalPort,OwningProcess
$base='http://127.0.0.1:3010'
$cred = Get-Content "$env:USERPROFILE\.dsh-qq\free-llm-api\dashboard-credentials.txt" -Encoding utf8
$email = ($cred | Where-Object { $_ -like '邮箱:*' }) -replace '邮箱:\s*',''
$pwd = ($cred | Where-Object { $_ -like '密码:*' }) -replace '密码:\s*',''
try{
 $r = Invoke-RestMethod -Uri "$base/api/auth/login" -Method Post -Body (@{email=$email;password=$pwd} | ConvertTo-Json) -ContentType 'application/json' -TimeoutSec 30
 $h = @{Authorization="Bearer $($r.token)"}
 $p = Invoke-RestMethod -Uri "$base/api/keys/providers" -Headers $h -TimeoutSec 30
 $list = $p; if($p.providers){ $list = $p.providers }
 "provider 数: $(@($list).Count)"
 (@($list) | Where-Object { "$($_.id)$($_.name)" -match 'agnes' } | Select-Object id,name,signupUrl,keyUrl,notes | Format-List | Out-String)
}catch{ "查询失败: $($_.Exception.Message)" }", "description": "重启网关并查 agnes provider"}

