content.arguments:
{"command": "$paths = @("$env:USERPROFILE\Documents","$env:USERPROFILE\Desktop","$env:USERPROFILE\Downloads","$env:USERPROFILE\AppData\Roaming")
$hits = @()
foreach($p in $paths){
  if(Test-Path $p){
    $files = Get-ChildItem $p -Recurse -File -ErrorAction SilentlyContinue |
      Where-Object { $_.Length -lt 2MB -and $_.FullName -notmatch 'node_modules|\\Cache\\|\\.git\\|Code Cache|GPUCache' -and $_.Extension -in '.txt','.md','.json','.env','.yaml','.yml','.ini','.log','.js','.ts','.py' }
    foreach($f in $files){
      $m = Select-String -Path $f.FullName -Pattern 'agnes' -SimpleMatch -ErrorAction SilentlyContinue -List
      if($m){ $hits += $f.FullName }
    }
  }
}
"命中 $(@($hits).Count) 个文件"
$hits | Select-Object -First 15", "description": "在用户文档与 AppData 中搜索 agnes 关键词", "timeoutMs": 240000}

